// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != address(0));
        vm.assume(value > 0 && value <= 1000000);
        // First, give some tokens to caller via mintToken
        uint256 initialBalance = 1000000;
        c.mintToken(caller, initialBalance);
        // Burn value tokens as caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));
        if (success) {
            uint256 expectedBalance = initialBalance - value;
            assertTrue(c.balanceOf(caller) == expectedBalance);
        } else {
            // If revert, balance unchanged
            assertTrue(c.balanceOf(caller) == initialBalance);
        }
    }
}

